package com.telecom.tollfree.service;
import com.telecom.tollfree.api.ApiModels.*; import com.telecom.tollfree.domain.Customer; import com.telecom.tollfree.repository.CustomerRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class CustomerService { private final CustomerRepository repo; public CustomerService(CustomerRepository r){repo=r;} private CustomerView view(Customer c){return new CustomerView(c.getId(),c.getName(),c.getEmail());} public CustomerView create(CustomerInput in){Customer c=new Customer();c.setName(in.name());c.setEmail(in.email());return view(repo.save(c));} @Transactional(readOnly=true) public CustomerView get(String id){return view(repo.findById(id).orElseThrow(()->new NotFoundException("Customer not found")));} public CustomerView update(String id,CustomerInput in){Customer c=repo.findById(id).orElseThrow(()->new NotFoundException("Customer not found"));c.setName(in.name());c.setEmail(in.email());return view(c);} @Transactional(readOnly=true) public Page<CustomerView> list(Pageable p){return repo.findAll(p).map(this::view);} public Customer require(String id){return repo.findById(id).orElseThrow(()->new NotFoundException("Customer not found"));} }
